.polytechnique-transcript{font:8px Arial,sans-serif;color:#111;padding:0 1mm 5mm;break-after:page;page-break-after:always}.poly-header{display:grid;grid-template-columns:1fr 70px 1fr;align-items:start;text-align:center;min-height:39px}.poly-official{font: bold 8px 'Times New Roman',serif;line-height:1.2}.poly-official[lang=fr]{text-align:center}.poly-official[lang=en]{text-align:center}.poly-university img{max-width:52px;max-height:44px;object-fit:contain}.poly-branding{display:grid;grid-template-columns:18% 64% 18%;align-items:center;text-align:center;margin:0 3%}.poly-logo img{max-width:70px;max-height:58px;object-fit:contain}.poly-school{font-size:8px;line-height:1.25;font-weight:bold}.poly-school strong{font-size:15px}.poly-red-rule{border-top:2px solid #c90018;border-bottom:1px solid #c90018;height:4px;margin:7px 0 5px}.polytechnique-transcript h1{text-align:center;font: bold 10px 'Times New Roman',serif;margin:7px 0}.poly-identity{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:8px;line-height:1.65;margin:0 1px 5px}.poly-marks,.poly-summary{border-collapse:collapse;width:100%;margin:0 0 4px;table-layout:fixed;font-size:7px}.poly-marks th,.poly-marks td,.poly-summary th,.poly-summary td{border:1px solid #222;padding:2px 3px;text-align:center;line-height:1.1}.poly-marks thead th{font-weight:bold}.poly-marks th:nth-child(1){width:7%}.poly-marks th:nth-child(2){width:7%}.poly-marks th:nth-child(3){width:30%}.poly-marks th:nth-child(4),.poly-marks th:nth-child(5){width:7%}.poly-marks th:nth-child(6),.poly-marks th:nth-child(7){width:8%}.poly-marks th:nth-child(8){width:8%}.poly-marks th:nth-child(9){width:10%}.poly-marks th:nth-child(10){width:8%}.poly-marks .poly-left{text-align:left}.poly-module{font-weight:bold}.poly-summary{font-size:7px;margin-top:8px}.poly-summary th{text-align:left}.poly-summary td{font-weight:bold}.poly-scale{font-size:6px;font-weight:bold;margin:3px 0}.poly-issued{text-align:center;margin:14px 0 10px;font-size:9px}.poly-signatures{display:flex;justify-content:space-between;font-size:10px;margin:0 0 2px}.poly-signatures strong:first-child{text-align:left}.poly-signatures strong:last-child{text-align:right}
@media print{.polytechnique-transcript{break-after:page;page-break-after:always}.polytechnique-transcript:last-of-type{break-after:auto;page-break-after:auto}}
